mapper.select:
SELECT 
FROM public.item_stat_modifiers
WHERE game_id = #{gameId}
  AND item_id = #{itemId}
ORDER BY attr_key

SELECT 
FROM public.item_stat_modifiers
WHERE game_id = #{gameId}
  AND updated_at > #{updatedAfter}
ORDER BY item_id, attr_key

mapper.delete:
DELETE FROM public.item_stat_modifiers
WHERE game_id = #{gameId}
  AND item_id = #{itemId}

mapper.update:
UPDATE public.item_stat_modifiers
SET start_version_id = #{versionId},
    end_version_id = #{versionId}
WHERE game_id = #{gameId}
  AND item_id = #{itemId}
  AND attr_key = #{attrKey}
